('LES Printshop Keyholder Residency','Lower East Side Printshop','residency','Nine months of free 24-hour printshop access in Manhattan, a $1,000 stipend and a show at the end.',1000,1000,'2027-05-31'::date,'https://www.printshop.org/keyholder-residency','Emerging artists in the NY metro area. Printmaking experience is helpful but not required. No fee. The Summer Keyholder residency ($500) is due Mar 1, 2027.',ARRAY['printmaking']::text[],'regional','New York metro','emerging',0,true,DATE '2026-09-24','https://www.printshop.org/keyholder-residency'),
('Artists Alliance LES Studio Program','Artists Alliance Inc.','residency','A free 3 or 6 month studio on the Lower East Side; New York State residents get a $500 monthly stipend.',1500,3000,NULL,'https://www.artistsallianceinc.org/programs/les-studio-program/','Emerging and mid-career artists, not students. No fee. Winter and summer calls are announced by newsletter; check the site.',ARRAY['painting','photography','sculpture','mixed_media','digital','printmaking','ceramics','drawing','textile','installation']::text[],'regional','Lower East Side, Manhattan','any',0,true,DATE '2026-09-24','https://www.artistsallianceinc.org/programs/les-studio-program/'),
('Jerome Hill Artist Fellowship','Jerome Foundation','fellowship','$60,000 over three years for early-career artists in Minnesota and NYC.',60000,60000,NULL,'https://www.jeromefdn.org/jerome-hill-artist-fellowship','Early-career artists living in Minnesota or the five boroughs. The next round opens in 2027; dates are TBA.',ARRAY['painting','photography','sculpture','mixed_media','digital','printmaking','ceramics','drawing','textile','installation']::text[],'regional','Minnesota and New York City','emerging',0,true,DATE '2026-09-24','https://www.jeromefdn.org/jerome-hill-artist-fellowship'),
('Wassaic Project Artist Residency','Wassaic Project','residency','Residencies in Dutchess County, NY on a sliding scale ($0 to $900 per session).',0,0,NULL,'https://www.wassaicproject.org/apply','Individuals, teams and families. $25 fee (waivable). The 2027 call has closed; the 2028 call isn''t announced yet.',ARRAY['painting','photography','sculpture','mixed_media','digital','printmaking','ceramics','drawing','textile','installation']::text[],'national','','any',25,true,DATE '2026-09-24','https://www.wassaicproject.org/apply'),
('Millay Arts Core Residency','Millay Arts','residency','A fully subsidized 2-week or 1-month residency in Austerlitz, NY; you pay only a $100 deposit.',0,0,'2026-10-01'::date,'https://www.millayarts.org/residencies/core-residency/','Multidisciplinary, blind jury. $45 fee (late deadline Oct 8, $65). For April to July 2027 sessions. The next deadline is March 1.',ARRAY['painting','photography','sculpture','mixed_media','digital','printmaking','ceramics','drawing','textile','installation']::text[],'national','','any',45,true,DATE '2026-09-24','https://www.millayarts.org/residencies/core-residency/')
) v(title, organization, opportunity_type, description, amount_min, amount_max, deadline, url, eligibility_notes, mediums, location_scope, location_detail, career_stage, application_fee, is_active, last_verified, source_url)
WHERE NOT EXISTS (SELECT 1 FROM public.opportunities o WHERE o.title = v.title AND o.organization = v.organization AND o.last_verified = DATE '2026-09-24');

SELECT count(*) FILTER (WHERE is_active) AS active,
       count(*) FILTER (WHERE is_active AND deadline >= current_date) AS dated,
       count(*) FILTER (WHERE is_active AND deadline IS NULL) AS rolling_or_tba
FROM public.opportunities;
